def link(text,url,cls='',extra=''): return f'<a class="{cls}" href="{url}" {extra}>{text}</a>'
def cta(text='Start a Project',query=''): return link(text,'/start-a-project'+query,'button button-primary')
def heading(title,sub='',eye=''): return f'<div class="section-heading"><div><p class="eyebrow">{eye}</p><h2>{title}</h2></div><p>{sub}</p></div>'
def section(id,title,content,sub='',eye=''): return f'<section class="section-shell section" id="{id}">{heading(title,sub,eye)}{content}</section>'
def grid(cards,cls='three-grid'): return f'<div class="{cls}">'+''.join(cards)+'</div>'
def card(title,body): return f'<article class="content-card"><h3>{title}</h3>{body}</article>'
header=f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="/" aria-label="Dick Mui home"><span class="brand-mark">DM</span><span>Dick Mui</span></a><a class="mobile-project" href="/start-a-project">Start a Project</a><button class="menu-button" aria-label="Open navigation" aria-controls="primary-nav" aria-expanded="false">Menu</button><nav class="nav" id="primary-nav" aria-label="Primary navigation">{''.join(link(t,u) for t,u in nav)}{link('Start a Project','/start-a-project','nav-cta')}</nav></header>'''
