def page(path,title,description,body,noindex=False,schema=None):
    url='https://dickmui-consulting.vercel.app'+('/' if path=='index' else '/'+path)
    if path != 'index': body = body.replace('<h2>', '<h1 class="page-title">', 1).replace('</h2>', '</h1>', 1)
    out=P/(path+'.html'); out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{url}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><meta property="og:image" content="https://dickmui-consulting.vercel.app/social-card.png"><meta name="twitter:card" content="summary_large_image">{'<meta name="robots" content="noindex,follow">' if noindex else ''}<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">{json.dumps(schema or {'@context':'https://schema.org','@type':'WebPage','name':title,'url':url})}</script></head><body>{header}<main id="main">{body}</main>{footer}<script src="/script.js" defer></script></body></html>''')
